'use strict';
const D=ZETA_CATALOG.domains,C=ZETA_COURSE_CATALOG.courses,K=ZETA_CATALOG.categories,R=ZETA_CATALOG.roles;
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const defaults={profile:{name:'Ayush',intention:'Build something worth knowing.',interests:[],skills:''},enrolled:[],completed:[],milestones:[],saved:[],domains:[],roles:[],notes:{},sessions:[],goals:[],compact:false,motion:false};
let state;try{state={...structuredClone(defaults),...JSON.parse(localStorage.getItem('zeta-web-state')||'{}')}}catch{state=structuredClone(defaults)}
let view={},limit=24,files=[],filter={q:'',cat:'All',level:'All',type:'All',source:'All',domain:'All',saved:false,mode:'grid',city:'Bengaluru',sort:'title'};
const icon=(name='book')=>{const p={home:'M3 10 12 3l9 7v10H3z M9 20v-7h6v7',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',book:'M3 4h7l2 2 2-2h7v16h-7l-2 1-2-1H3z M12 6v15',folder:'M3 6h7l2 3h9v11H3z',briefcase:'M3 8h18v12H3z M8 8V4h8v4 M3 13h18 M10 13v3h4v-3',user:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M4 21v-2a8 8 0 0 1 16 0v2',chart:'M4 20V10 M12 20V4 M20 20v-7',search:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14 M15 15l6 6',arrow:'M4 12h16 M14 6l6 6-6 6',plus:'M12 4v16 M4 12h16',bookmark:'M6 3h12v18l-6-4-6 4z',clock:'M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18 M12 6v6l4 2',check:'M4 12l5 5L20 6',menu:'M4 6h16 M4 12h16 M4 18h16',zap:'M13 2 4 14h7l-1 8 10-13h-7z',file:'M5 3h9l5 5v13H5z M14 3v6h5 M8 13h8 M8 17h6',close:'M5 5l14 14 M19 5 5 19',upload:'M12 16V3 M6 9l6-6 6 6 M4 16v5h16v-5',target:'M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18 M12 16a4 4 0 1 0 0-8 4 4 0 0 0 0 8'};return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${p[name]||p.book}"/></svg>`};
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3000)}
function save(){try{localStorage.setItem('zeta-web-state',JSON.stringify(state));return true}catch{toast('Storage is unavailable. Your change could not be saved.');return false}}
function mutate(fn,message){const previous=structuredClone(state);fn();if(save()){if(message)toast(message);render()}else {state=previous;render()}}
const pct=c=>Math.round(c.modules.filter(m=>state.completed.includes(m.id)).length/c.modules.length*100);
const route=(page,id,tab)=>`#/${page}${id!=null?'/'+id:''}${tab?'/'+tab:''}`;
const btn=(text,href,black=false)=>`<a class="btn ${black?'black':''}" href="${href}">${text}${icon('arrow')}</a>`;
const bookmark=(kind,id)=>`<button class="bookmark ${state[kind].includes(id)?'saved':''}" aria-label="${state[kind].includes(id)?'Unsave':'Save'} ${kind==='domains'?'domain':kind==='roles'?'career path':'resource'}" data-action="bookmark" data-kind="${kind}" data-id="${esc(id)}">${icon('bookmark')}</button>`;
const tags=arr=>arr.map(s=>`<span class="tag">${esc(s)}</span>`).join('');
const empty=(title,text,action='')=>`<div class="empty"><h3>${title}</h3><p>${text}</p>${action}</div>`;
function shell(){const nav=[['dashboard','home','Dashboard'],['domains','grid','Domains'],['courses','book','Courses'],['knowledge','folder','Knowledge'],['jobs','briefcase','Jobs']];$('#sidebar').innerHTML=`<a class="brand" href="#/dashboard">${icon('zap')}ZETA</a><div class="navlabel">YOUR WORKSPACE</div>${nav.map(([id,i,t])=>`<a class="nav ${view.page===id?'active':''}" href="#/${id}">${icon(i)}${t}</a>`).join('')}<div class="sidebar-bottom"><a class="nav ${view.page==='analytics'?'active':''}" href="#/analytics">${icon('chart')}Analytics</a><a class="nav ${view.page==='profile'?'active':''}" href="#/profile">${icon('user')}Profile & settings</a><div class="side-note"><b>A little, every day.</b><br>Keep your curiosity in motion.<br>Stored on this browser.</div></div>`;const label=nav.find(n=>n[0]===view.page)?.[2]||({profile:'Profile & settings',analytics:'Analytics'}[view.page])||'Workspace';$('#topbar').innerHTML=`<button class="menu-toggle" data-action="menu" aria-label="Open navigation" aria-expanded="false">${icon('menu')}</button><div class="crumb">Workspace / <b>${label}</b></div><div class="top-actions"><button class="search-trigger" data-action="search" aria-label="Search everything">${icon('search')}<span class="search-text">Search your universe</span><span class="key">⌘ K</span></button><button class="black" data-action="session">${icon('plus')}New study session</button><a class="btn avatar" href="#/profile" aria-label="Open your profile">${esc(state.profile.name.charAt(0).toUpperCase())}</a></div>`;document.body.classList.toggle('compact',state.compact);document.body.classList.toggle('reduce-motion',state.motion);syncDrawer()}
function head(eyebrow,title,sub,action=''){return `<div class="pagehead"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function metric(label,value,note,i='chart',color=''){return `<article class="metric"><div class="metric-top">${label}<span class="iconbox ${color}">${icon(i)}</span></div><strong>${value}</strong><span class="small">${note}</span></article>`}
function localDate(date=new Date()){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function weekly(){return Array.from({length:7},(_,n)=>{const date=new Date();date.setDate(date.getDate()-6+n);return {label:date.toLocaleDateString('en',{weekday:'short'}),minutes:state.sessions.filter(s=>s.date===localDate(date)).reduce((a,s)=>a+s.minutes,0)}})}
function chart(){const data=weekly(),max=Math.max(60,...data.map(d=>d.minutes));return `<div class="bar-chart">${data.map(d=>`<div class="bar-column" title="${d.minutes} minutes"><i style="height:${d.minutes/max*100}%"></i><span>${d.label}</span></div>`).join('')}</div><p class="chart-note">${data.reduce((a,d)=>a+d.minutes,0)} minutes logged in the last 7 days</p>`}
function courseCard(c){const enrolled=state.enrolled.includes(c.id);return `<article class="card"><div class="card-head"><span class="iconbox ${c.primaryDomainId%3===0?'blue':c.primaryDomainId%3===1?'peach':''}">${icon('book')}</span><span class="small">~${c.estimatedHours}h estimate · ${c.modules.length} modules</span></div><a href="${route('courses',c.id)}"><h3>${esc(c.title)}</h3></a><p>${esc(c.summary)}</p><div style="margin-top:14px">${tags([c.level,...c.skills.slice(0,2)])}</div>${enrolled?`<div class="progress"><i style="width:${pct(c)}%"></i></div><span class="small">${pct(c)}% complete · self-reported checkpoints</span>`:''}<div class="card-bottom"><span class="small">${esc(c.category)}</span><a class="textlink" href="${route('courses',c.id)}">${enrolled?'Continue':'Explore course'} ↗</a></div></article>`}
function domainCard(d){return `<article class="card"><div class="card-head"><span class="iconbox ${d.id%4===0?'blue':d.id%4===1?'peach':d.id%4===2?'yellow':''}">${icon('grid')}</span>${bookmark('domains',d.id)}</div><a href="${route('domains',d.id)}"><h3>${esc(d.name)}</h3></a><p>${esc(ZETA_DOMAIN_CONTENT[d.id].about.split('. ')[0])}.</p><div style="margin-top:12px">${tags(d.skills.slice(0,3))}</div><div class="card-bottom"><span class="small">${esc(d.category)}</span><a href="${route('domains',d.id)}" aria-label="Explore ${esc(d.name)}">${icon('arrow')}</a></div></article>`}
function dashboard(){const enrolled=C.filter(c=>state.enrolled.includes(c.id)),minutes=state.sessions.reduce((a,s)=>a+s.minutes,0),goals=state.goals.filter(g=>!g.done),rec=state.profile.interests.length?C.filter(c=>state.profile.interests.includes(c.category)).slice(0,2):C.slice(0,2);return head('THE KNOWLEDGE ATELIER',`Good to see you, ${esc(state.profile.name)}.`, 'A considered space for the things you want to learn. Make today a small step forward.',`<span class="small">${new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long'})}</span>`)+`<section class="hero"><div class="hero-copy"><div class="eyebrow">A LITTLE CURIOSITY. A LOT OF POSSIBILITY.</div><h2>Your next chapter<br>starts with a question.</h2><p>${esc(state.profile.intention)}</p>${btn('Find your learning path',route('courses'))}</div><div class="hero-goal"><div><span class="eyebrow">THIS WEEK, INTENTIONALLY</span><div class="big">${weekly().reduce((a,d)=>a+d.minutes,0)}<span style="font:14px Segoe UI;margin-left:8px">min</span></div><p>Time you've made for learning</p></div><div><div class="progress"><i style="width:${Math.min(100,weekly().reduce((a,d)=>a+d.minutes,0)/180*100)}%"></i></div><p>Build your rhythm. One session at a time.</p></div></div></section><div class="metrics">${metric('Active courses',enrolled.filter(c=>pct(c)<100).length,'Your current learning paths','book')}${metric('Checkpoints completed',state.completed.length,'Across your enrolled courses','check','blue')}${metric('Study time',(minutes/60).toFixed(1)+'h','From your logged sessions','clock','peach')}${metric('Saved resources',state.saved.length,'Your personal reference shelf','bookmark','yellow')}</div><div class="dashboard-grid"><div><section class="panel"><div class="section-head"><h2>Continue learning</h2><a class="textlink" href="#/courses/my-learning">My learning ↗</a></div>${enrolled.length?enrolled.slice(0,3).map(c=>`<a class="row" href="${route('courses',c.id,'syllabus')}"><span class="iconbox">${icon('book')}</span><div class="grow"><h3>${esc(c.title)}</h3><div class="progress"><i style="width:${pct(c)}%"></i></div><span class="small">${c.modules.filter(m=>state.completed.includes(m.id)).length} of ${c.modules.length} checkpoints</span></div>${icon('arrow')}</a>`).join(''):empty('Your first chapter is waiting.','Explore a course and add it to your learning space. Your progress will appear here.',btn('Explore courses','#/courses',true))}</section><section><div class="section-head"><h2>${state.profile.interests.length?'For your interests':'A few places to begin'}</h2><span class="small">${state.profile.interests.length?'Interest matches':'Featured curricula'}</span></div><div class="cards" style="grid-template-columns:repeat(2,1fr)">${rec.map(courseCard).join('')}</div></section></div><div><section class="panel"><div class="section-head"><h2>Learning rhythm</h2><a class="textlink" href="#/analytics">View insights ↗</a></div>${chart()}</section><section class="panel"><div class="section-head"><h2>Your intentions</h2><button data-action="goal" aria-label="Add a goal">${icon('plus')}</button></div>${goals.length?goals.slice(0,3).map(g=>`<div class="row"><span class="iconbox yellow">${icon('target')}</span><div class="grow"><h3>${esc(g.title)}</h3><span class="small">Target: ${esc(g.date||'Whenever you are ready')}</span></div></div>`).join(''):empty('Give curiosity a direction.','Set a small goal you can make room for.','<button data-action="goal">Create a learning goal</button>')}</section><section class="panel"><div class="section-head"><h2>Skills in motion</h2><a class="textlink" href="#/domains">Discover ↗</a></div>${enrolled.length?tags([...new Set(enrolled.flatMap(c=>c.skills))].slice(0,8)):'<p class="small">Skills from your enrolled courses will grow here.</p>'}</section></div></div><section class="panel" style="margin-top:24px"><div class="section-head"><h2>Your recent footsteps</h2><a class="textlink" href="#/knowledge">Open your library ↗</a></div>${state.sessions.length?state.sessions.slice().reverse().slice(0,3).map(s=>`<div class="row"><span class="iconbox">${icon('clock')}</span><div class="grow"><h3>${esc(s.title)}</h3><span class="small">${s.date} · ${s.minutes} minutes</span></div>${icon('check')}</div>`).join(''):'<p class="small">No study sessions logged yet. Your own learning activity will appear here.</p>'}</section>${state.domains.length?`<section><div class="section-head"><h2>Your domain shortlist</h2></div><div class="cards">${D.filter(d=>state.domains.includes(d.id)).slice(0,3).map(domainCard).join('')}</div></section>`:''}`}
function categories(course=false){return `<div class="categories">${['All',...K].map(k=>`<button data-cat="${esc(k)}" class="${filter.cat===k?'active':''}">${esc(k)} <span class="small">${k==='All'?(course?C:D).length:(course?C:D).filter(d=>d.category===k).length}</span></button>`).join('')}</div>`}
function searchFilters(extra=''){return `<div class="filters"><input aria-label="Search catalogue" data-filter="q" type="search" placeholder="Search topics, skills, or titles…" value="${esc(filter.q)}">${extra}<button data-action="toggle-saved" aria-pressed="${filter.saved}">${icon('bookmark')}${filter.saved?'Saved only':'All items'}</button></div>`}
function more(count){return count>limit?'<div class="loadmore"><button data-action="more">Load more '+icon('arrow')+'</button></div>':''}
function domains(){const list=D.filter(d=>(filter.cat==='All'||d.category===filter.cat)&&(!filter.saved||state.domains.includes(d.id))&&`${d.name} ${d.skills.join(' ')} ${d.roles.join(' ')}`.toLowerCase().includes(filter.q.toLowerCase())).sort((a,b)=>filter.sort==='title'?a.name.localeCompare(b.name):a.id-b.id);return head('AN ATLAS OF POSSIBILITY','Find your field.','102 domains. Connected ideas. Start somewhere that makes you curious.')+categories()+searchFilters(`<label class="filter-label"><span>Sort domains</span><select aria-label="Sort domains" data-filter="sort"><option value="title">Name A–Z</option><option value="original" ${filter.sort==='original'?'selected':''}>Editorial order</option></select></label>`)+`<div class="section-head"><span class="small">${list.length} domains to explore</span></div><div class="cards">${list.slice(0,limit).map(domainCard).join('')}</div>${!list.length?empty('No domains found.','Try another keyword or category.'):''}${more(list.length)}`}
function courses(){if(view.id==='my-learning')return learning();const list=C.filter(c=>(filter.cat==='All'||c.category===filter.cat)&&(filter.level==='All'||c.level===filter.level)&&`${c.title} ${c.skills.join(' ')}`.toLowerCase().includes(filter.q.toLowerCase()));return head('LEARN WITH INTENTION','A course. A practice. A possibility.','Original ZETA study paths, grounded in trusted references. Your next project begins here.')+`<nav class="tabs"><a class="active" href="#/courses">Explore courses</a><a href="#/courses/my-learning">My learning · ${state.enrolled.length}</a></nav>`+categories(true)+`<div class="filters"><input aria-label="Search courses" data-filter="q" type="search" placeholder="Search courses or skills…" value="${esc(filter.q)}"><label class="filter-label"><span>Course level</span><select aria-label="Course level" data-filter="level">${['All','beginner','intermediate','advanced'].map(l=>`<option ${filter.level===l?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="section-head"><span class="small">${list.length} authored courses · 145 learning modules</span><span class="small">Self-paced. Self-reported progress.</span></div><div class="cards">${list.map(courseCard).join('')}</div>${!list.length?empty('No matching courses.','Try a different category or level.'):''}`}
function tabnav(page,id,tabs,active){return `<nav class="tabs">${tabs.map(t=>`<a class="${t.toLowerCase()===active?'active':''}" href="${route(page,id,t.toLowerCase())}">${t}</a>`).join('')}</nav>`}
let resources=[];const byURL=new Map();function addResource(r,domain,course){if(!r.url||!/^https?:\/\//.test(r.url))return;let item=byURL.get(r.url);if(!item){item={...r,key:r.url,domains:[],courses:[],levels:[],types:[],sources:[]};byURL.set(r.url,item)}if(domain!=null&&!item.domains.includes(domain))item.domains.push(domain);if(course&&!item.courses.includes(course))item.courses.push(course);if(r.level&&!item.levels.includes(r.level))item.levels.push(r.level);const type=r.type||'doc';if(!item.types.includes(type))item.types.push(type);const source=r.source||'other';if(!item.sources.includes(source))item.sources.push(source)}
D.forEach(d=>ZETA_LEARNING_PATHS[d.id].resources.forEach(r=>addResource(r,d.id)));C.forEach(c=>c.modules.forEach(m=>m.resources.forEach(r=>addResource(r,c.primaryDomainId,c.id))));resources=[...byURL.values()];
const format=r=>r.type==='pdf'?'PDF':r.type==='video'?'Video':r.type==='course'?'Course':r.type==='repo'?'GitHub':'Docs';
function resourceCard(r){const domain=byURL.get(r.url)?.domains[0];return `<article class="resource"><div class="card-head" style="margin-bottom:0"><span class="iconbox ${r.type==='video'?'peach':r.type==='pdf'?'blue':''}">${icon(r.type==='video'?'zap':'file')}</span>${bookmark('saved',r.url)}</div><h3>${esc(r.title)}</h3><div class="small">${format(r)} · ${esc(r.source||'Publisher')} · ${esc(r.level||'mixed levels')}${r.discovery?' · Platform search':''}</div>${domain!=null?`<span class="tag">${esc(D[domain].name)}</span>`:''}<div class="resource-actions"><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${r.discovery?'Find on platform':r.type==='pdf'?'Open publisher PDF':'Open reference'} ↗</a><span class="small">Online source</span></div></article>`}
function resourceMatches(r){const type={PDF:'pdf',Videos:'video',Courses:'course',GitHub:'repo',Docs:'doc'}[filter.type];return (!type||r.types.includes(type))&&(filter.source==='All'||r.sources.includes(filter.source))&&(filter.level==='All'||r.levels.includes(filter.level))&&(filter.domain==='All'||r.domains.includes(+filter.domain))&&(filter.cat==='All'||r.domains.some(id=>D[id].category===filter.cat))&&(!filter.saved||state.saved.includes(r.url))&&`${r.title} ${r.domains.map(id=>D[id].name).join(' ')}`.toLowerCase().includes(filter.q.toLowerCase())}
function options(values,current){return values.map(t=>`<option ${current===t?'selected':''}>${esc(t)}</option>`).join('')}
function resourceSection(items){const unique=[...new Map(items.map(r=>[r.url,r])).values()],list=unique.filter(r=>resourceMatches(byURL.get(r.url)||{...r,domains:[],levels:[r.level],types:[r.type],sources:[r.source]}));return searchFilters(`<label class="filter-label"><span>Resource format</span><select aria-label="Resource format" data-filter="type">${options(['All','PDF','Videos','Courses','GitHub','Docs'],filter.type)}</select></label><label class="filter-label"><span>Resource source</span><select aria-label="Resource source" data-filter="source">${options(['All','youtube','coursera','udemy','github','other'],filter.source)}</select></label>`)+`<p class="small" style="margin-bottom:18px">${list.length} references · external publishers and labelled discovery searches</p><div class="resources">${list.slice(0,limit).map(resourceCard).join('')}</div>${!list.length?empty('No references match.','Try a different format or source.'):''}${more(list.length)}`}
function domainDetail(){const d=D.find(d=>d.id===+view.id);if(!d)return missing();const o=ZETA_DOMAIN_CONTENT[d.id],path=ZETA_LEARNING_PATHS[d.id],tab=view.tab||'about';let content='';if(tab==='about')content=`<section class="panel"><h2>What is ${esc(d.name)}?</h2><p>${esc(o.about)}</p><h3>Where the idea becomes useful</h3><ul>${o.applications.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><h3>Before you begin</h3><ul>${o.prerequisites.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></section><section class="panel"><h2>A project to make it yours</h2><p>${esc(d.project)}</p><p>${esc(d.task)}</p>${btn('Open the learning roadmap',route('domains',d.id,'roadmap'),true)}</section>`;if(tab==='basics')content=o.basics.map((b,i)=>`<section class="panel"><div class="eyebrow">FOUNDATION ${i+1}</div><h2>${esc(o.subjects[i]||d.name)}</h2><p>${esc(b)}</p></section>`).join('');if(tab==='roadmap')content=path.stages.map((s,i)=>`<section class="panel lesson" id="stage-${i}"><div class="eyebrow">STAGE 0${i+1} / ${esc(s.level)}</div><h2>${esc(s.title)}</h2><p>${esc(s.goal)}</p>${tags(s.topics)}<h3 style="margin-top:20px">Put it into practice</h3><p>${esc(s.exercise)}</p><div class="check"><input id="milestone-${i}" type="checkbox" data-milestone="${d.id}-${s.id}" ${state.milestones.includes(`${d.id}-${s.id}`)?'checked':''}><label for="milestone-${i}"><b>Self-assessed checkpoint</b><br>${esc(s.checkpoint)}</label></div><div class="resources">${s.resources.map(resourceCard).join('')}</div></section>`).join('');if(tab==='resources')content=resourceSection(path.resources);if(tab==='jobs')content=`<div class="cards" style="grid-template-columns:1fr">${R.filter(r=>d.roles.includes(r.title)).map(roleCard).join('')}</div>`;if(tab==='insights')content=`<section class="panel"><h2>A note from the atelier</h2><p class="small">Authored learning guidance — not live industry news</p>${o.insights.map(i=>`<p>${esc(i)}</p>`).join('')}</section><section class="panel"><h2>Your learning updates</h2><p>${state.milestones.filter(m=>m.startsWith(d.id+'-')).length} of 4 roadmap checkpoints marked on this browser.</p>${btn('Continue your roadmap',route('domains',d.id,'roadmap'))}</section>`;return head(esc(d.category),esc(d.name),esc(d.skills.join(' · ')),bookmark('domains',d.id))+tabnav('domains',d.id,['About','Basics','Roadmap','Resources','Jobs','Insights'],tab)+`<div class="detail-layout"><aside class="outline"><h3>YOUR DOMAIN WORKSPACE</h3>${path.stages.map((s,i)=>`<a href="${route('domains',d.id,'roadmap')}">0${i+1} · ${esc(s.title)}</a>`).join('')}<button data-action="pdf" data-domain="${d.id}" style="margin-top:20px;width:100%">${icon('file')}Study planner PDF</button><p class="small" style="margin-top:14px">An offline worksheet for your next study session.</p></aside><div class="detail-content">${content}<button data-action="pdf" data-domain="${d.id}">${icon('file')}Download ${esc(d.name)} study planner</button></div></div>`}
function courseDetail(){const c=C.find(c=>c.id===view.id);if(!c)return missing();const tab=view.tab||'overview',enrolled=state.enrolled.includes(c.id);let content='';if(tab==='overview')content=`<section class="panel"><h2>Make the knowledge tangible.</h2><p>${esc(c.summary)}</p>${tags(c.skills)}<h3 style="margin-top:25px">By the end of this path</h3><ul>${c.outcomes.map(o=>`<li>${esc(o)}</li>`).join('')}</ul><h3>Before you begin</h3><ul>${c.prerequisites.map(o=>`<li>${esc(o)}</li>`).join('')}</ul><p class="small">ZETA-authored curriculum. Study time is an estimate. Completion records are your own self-assessment.</p></section>`;if(tab==='syllabus'||tab==='roadmap')content=c.modules.map((m,i)=>`<section class="panel lesson" id="module-${i}"><div class="eyebrow">MODULE 0${i+1} / ${esc(m.level)}</div><h2>${esc(m.title)}</h2><ul>${m.objectives.map(o=>`<li>${esc(o)}</li>`).join('')}</ul><h3>Your practice</h3><p>${esc(m.practice)}</p><div class="check"><input type="checkbox" id="checkpoint-${i}" data-module="${m.id}" ${state.completed.includes(m.id)?'checked':''} ${!enrolled?'disabled':''}><label for="checkpoint-${i}"><b>Mark your checkpoint ${!enrolled?'— enroll to track progress':''}</b><br>${esc(m.checkpoint)}</label></div><div class="resources">${m.resources.map(resourceCard).join('')}</div><div class="formfield" style="margin-top:24px"><label for="note-${i}">Your reflection · saved on this browser</label><textarea id="note-${i}" data-note="${m.id}" placeholder="What did you notice? What would you try next?">${esc(state.notes[m.id]||'')}</textarea><button data-action="note" data-id="${m.id}">Save reflection</button></div>${i<c.modules.length-1?`<a class="textlink" href="#module-${i+1}" data-scroll="module-${i+1}">Next module ↓</a>`:''}</section>`).join('');if(tab==='resources')content=resourceSection(c.modules.flatMap(m=>m.resources));if(tab==='progress')content=`<section class="panel"><h2>${pct(c)}% of your course checkpoints</h2><div class="progress"><i style="width:${pct(c)}%"></i></div><p>${c.modules.filter(m=>state.completed.includes(m.id)).length} of ${c.modules.length} marked. This is a personal learning record.</p>${c.modules.map(m=>`<div class="row">${icon(state.completed.includes(m.id)?'check':'book')}<h3>${esc(m.title)}</h3></div>`).join('')}</section><section class="panel"><div class="section-head"><h2>A goal for this course</h2><button data-action="goal" data-course="${c.id}">${icon('plus')}Add goal</button></div>${state.goals.filter(g=>g.course===c.id).map(goalRow).join('')||'<p class="small">No course goals yet. Set a target for a checkpoint or a project.</p>'}</section>`;return head(esc(c.category)+' / '+esc(c.level),esc(c.title),`${c.estimatedHours} estimated study hours · ${c.modules.length} modules · ZETA authored`,enrolled?btn(pct(c)===100?'Review course':'Continue learning',route('courses',c.id,'syllabus'),true):`<button class="black" data-action="enroll" data-id="${c.id}">${icon('plus')}Add to my learning</button>`)+tabnav('courses',c.id,['Overview','Syllabus','Roadmap','Resources','Progress'],tab)+`<div class="detail-layout"><aside class="outline"><h3>YOUR COURSE OUTLINE</h3>${c.modules.map((m,i)=>`<a href="${route('courses',c.id,'syllabus')}" data-lesson="${i}">${state.completed.includes(m.id)?'✓':'0'+(i+1)} · ${esc(m.title)}</a>`).join('')}<div class="progress"><i style="width:${pct(c)}%"></i></div><p class="small">${pct(c)}% complete</p><button data-action="session" data-course="${c.id}" style="margin-top:18px">${icon('clock')}Log study time</button></aside><div class="detail-content">${content}</div></div>`}
function knowledge(){if(view.id==='vault')return vault();const list=resources.filter(resourceMatches).sort((a,b)=>filter.sort==='source'?(a.source||'').localeCompare(b.source||''):a.title.localeCompare(b.title));return head('YOUR REFERENCE SHELF','Good ideas deserve a home.','A curated library of references, textbooks, videos and courses. Save what you want to return to.',`<button data-action="upload">${icon('upload')}Add a file</button>`)+`<nav class="tabs"><a class="active" href="#/knowledge">Explore references</a><a href="#/knowledge/vault">My vault · ${files.length} files</a></nav>`+searchFilters(`<label class="filter-label"><span>Resource format</span><select aria-label="Resource format" data-filter="type">${options(['All','PDF','Videos','Courses','GitHub','Docs'],filter.type)}</select></label><button data-action="view-mode">${icon('grid')}${filter.mode==='grid'?'Table':'Grid'}</button>`)+`<div class="filters"><label class="filter-label"><span>Resource category</span><select aria-label="Resource category" data-filter="cat">${options(['All',...K],filter.cat)}</select></label><label class="filter-label"><span>Resource domain</span><select aria-label="Resource domain" data-filter="domain"><option value="All">All domains</option>${D.map(d=>`<option value="${d.id}" ${filter.domain===String(d.id)?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label><label class="filter-label"><span>Resource source</span><select aria-label="Resource source" data-filter="source">${options(['All','youtube','coursera','udemy','github','other'],filter.source)}</select></label><label class="filter-label"><span>Resource level</span><select aria-label="Resource level" data-filter="level">${options(['All','beginner','intermediate','advanced'],filter.level)}</select></label><label class="filter-label"><span>Sort resources</span><select aria-label="Sort resources" data-filter="sort"><option value="title">Title A–Z</option><option value="source" ${filter.sort==='source'?'selected':''}>Source</option></select></label></div><div class="section-head"><span class="small">${list.length} references · deduplicated by source URL</span><button data-action="reset">Reset filters</button></div>${filter.mode==='grid'?`<div class="cards">${list.slice(0,limit).map(resourceCard).join('')}</div>`:`<table class="resource-table"><thead><tr><th>Reference</th><th>Domain</th><th>Format</th><th>Save</th></tr></thead><tbody>${list.slice(0,limit).map(r=>`<tr><td><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ↗</a><p class="small">${r.discovery?'Platform search':'Publisher reference'}</p></td><td>${r.domains.slice(0,2).map(id=>esc(D[id].name)).join(' · ')}</td><td>${format(r)}</td><td>${bookmark('saved',r.url)}</td></tr>`).join('')}</tbody></table>`}${!list.length?empty('Nothing on this shelf yet.','Change your filters or save a reference.'):''}${more(list.length)}`}
function roleCard(r){const d=D.find(d=>r.domainNames.includes(d.name)),city=filter.city==='Remote'?'remote':filter.city;return `<article class="card"><div class="card-head"><span class="iconbox peach">${icon('briefcase')}</span>${bookmark('roles',r.id)}</div><h3>${esc(r.title)}</h3><p>${esc(r.responsibilities)}</p><div style="margin:14px 0">${tags(r.skills)}</div><p class="small">${esc(r.qualifications)}</p><div style="margin:16px 0"><b>${esc(r.package)}</b><p class="small">India annual CTC · junior 0–3 years<br>${r.salarySource?`<a href="${r.salarySource}" target="_blank" rel="noopener noreferrer">2026 Talpro placement guide ↗</a>`:'No comparable salary benchmark supplied'}</p></div><div class="card-bottom">${d?`<a class="textlink" href="${route('domains',d.id)}">Learn for this role ↗</a>`:''}<a class="textlink" href="https://www.linkedin.com/jobs/search/?keywords=${encodeURIComponent(r.title)}&location=${encodeURIComponent(city)}" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a></div><div class="resource-actions"><a href="https://www.naukri.com/jobs-in-${encodeURIComponent(city.toLowerCase())}?k=${encodeURIComponent(r.title)}" target="_blank" rel="noopener noreferrer">Naukri ↗</a><a href="https://in.indeed.com/jobs?q=${encodeURIComponent(r.title)}&l=${encodeURIComponent(city)}" target="_blank" rel="noopener noreferrer">Indeed ↗</a></div></article>`}
function jobs(){const list=R.filter(r=>(!filter.saved||state.roles.includes(r.id))&&(filter.cat==='All'||D.some(d=>r.domainNames.includes(d.name)&&d.category===filter.cat))&&(filter.domain==='All'||r.domainNames.includes(D[+filter.domain]?.name))&&`${r.title} ${r.skills.join(' ')} ${r.domainNames.join(' ')}`.toLowerCase().includes(filter.q.toLowerCase()));return head('KNOWLEDGE MEETS POSSIBILITY','Build toward what comes next.','Explore 24 career paths and the skills behind them. Job buttons open live searches on the named platform.')+searchFilters(`<label class="filter-label"><span>Job city preference</span><select aria-label="Job city preference" data-filter="city">${options(['Bengaluru','Hyderabad','Pune','Mumbai','Delhi','Chennai','Remote'],filter.city)}</select></label>`)+`<div class="filters"><label class="filter-label"><span>Career category</span><select aria-label="Career category" data-filter="cat">${options(['All',...K],filter.cat)}</select></label><label class="filter-label"><span>Career domain</span><select aria-label="Career domain" data-filter="domain"><option value="All">All domains</option>${D.map(d=>`<option value="${d.id}" ${filter.domain===String(d.id)?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label></div><p class="small" style="margin-bottom:25px">${list.length} career paths · salary guide context, not vacancy listings or guaranteed offers</p><div class="cards">${list.map(roleCard).join('')}</div>${!list.length?empty('No paths match these filters.','Try another skill, category or domain.'):''}`}
function goalRow(g){const c=C.find(c=>c.id===g.course);return `<article class="goal-row"><div class="row"><input type="checkbox" aria-label="Complete ${esc(g.title)}" data-goal="${g.id}" ${g.done?'checked':''} style="min-height:auto;width:18px;height:18px"><div class="grow"><h3 style="${g.done?'text-decoration:line-through':''}">${esc(g.title)}</h3><span class="small">${esc(g.date||'No target date')}${c?' · '+esc(c.title):''}${g.checkpoint?' · '+esc(c?.modules.find(m=>m.id===g.checkpoint)?.title||''):''}</span></div><button data-action="edit-goal" data-id="${g.id}">Edit</button><button data-action="delete-goal" data-id="${g.id}" aria-label="Delete goal">${icon('close')}</button></div></article>`}
function learning(){const tab=view.tab||'tracker',enrolled=C.filter(c=>state.enrolled.includes(c.id));return head('MAKE IT YOUR OWN','My learning. My pace.','Your courses, intentions and personal notes — kept independently on this browser.')+`<nav class="tabs"><a href="#/courses">Explore courses</a><a class="active" href="#/courses/my-learning">My learning</a></nav>`+tabnav('courses','my-learning',['Tracker','Goals','Vault'],tab)+(tab==='tracker'?`<div class="cards">${enrolled.map(courseCard).join('')}</div>${!enrolled.length?empty('A blank page. A good beginning.','Add a course from Explore to begin tracking your learning.',btn('Browse all courses','#/courses',true)):''}`:tab==='goals'?`<section class="panel"><div class="section-head"><h2>Your learning intentions</h2><button class="black" data-action="goal">${icon('plus')}New goal</button></div>${state.goals.map(goalRow).join('')||empty('Start with a small intention.','A good goal makes your next step clearer.')}</section>`:vault(true))}
function analytics(){const total=state.sessions.reduce((a,s)=>a+s.minutes,0),complete=C.filter(c=>state.enrolled.includes(c.id)&&pct(c)===100);return head('THE SHAPE OF YOUR PRACTICE','Small steps leave a trail.','An honest picture of your learning, built from the sessions and checkpoints you record.',`<button class="black" data-action="session">${icon('plus')}Log a session</button>`)+`<div class="metrics">${metric('Logged study time',(total/60).toFixed(1)+'h','Across all saved sessions','clock')}${metric('Sessions',state.sessions.length,'Manually recorded by you','chart','blue')}${metric('Completed courses',complete.length,'All course checkpoints checked','check','peach')}${metric('Roadmap milestones',state.milestones.length,'Your domain checkpoints','target','yellow')}</div><div class="twocol"><section class="panel"><div class="section-head"><h2>This week's practice</h2></div>${chart()}</section><section class="panel"><h2>Study by learning path</h2>${state.enrolled.length?C.filter(c=>state.enrolled.includes(c.id)).map(c=>`<div class="row"><div class="grow"><h3>${esc(c.title)}</h3><div class="progress"><i style="width:${pct(c)}%"></i></div><span class="small">${pct(c)}% checkpoints · ${state.sessions.filter(s=>s.course===c.id).reduce((a,s)=>a+s.minutes,0)} minutes logged</span></div></div>`).join(''):'<p style="margin-top:18px">Enroll in a course to see your learning paths here.</p>'}</section></div><section class="panel"><div class="section-head"><h2>Your study journal</h2><button data-action="session">Add a record</button></div>${state.sessions.length?state.sessions.slice().reverse().map(s=>`<div class="row"><span class="iconbox">${icon('clock')}</span><div class="grow"><h3>${esc(s.title)}</h3><span class="small">${s.date} · ${s.minutes} minutes${s.course?' · '+esc(C.find(c=>c.id===s.course)?.title||''):''}</span></div><button data-action="delete-session" data-id="${s.id}" aria-label="Delete study session">${icon('close')}</button></div>`).join(''):empty('Your journal is ready.','Log a session after you spend time learning. All charts begin with your own records.')}</section>`}
function profile(){return head('A SPACE THAT FEELS LIKE YOU','Your learning identity.','Let your interests shape what you find here. You can change direction whenever you want.')+`<div class="twocol"><section class="panel"><h2>Your profile</h2><form id="profile-form" style="margin-top:25px"><div class="formfield"><label for="profile-name">Preferred name</label><input id="profile-name" name="name" maxlength="60" required value="${esc(state.profile.name)}"></div><div class="formfield"><label for="profile-intention">Learning intention</label><input id="profile-intention" name="intention" maxlength="200" value="${esc(state.profile.intention)}"></div><div class="formfield"><label for="profile-skills">Skills you identify with · self-declared</label><textarea id="profile-skills" name="skills" placeholder="Python, design thinking, problem solving…">${esc(state.profile.skills)}</textarea></div><div class="formfield"><label>Your interests</label><div class="categories">${K.map(k=>`<label class="tag" style="padding:10px"><input name="interests" type="checkbox" value="${esc(k)}" ${state.profile.interests.includes(k)?'checked':''} style="min-height:auto;margin-right:8px">${esc(k)}</label>`).join('')}</div></div><button class="black" type="submit">Save your profile</button></form></section><div><section class="panel"><h2>A few preferences</h2><div class="check"><input type="checkbox" id="compact" data-setting="compact" ${state.compact?'checked':''}><label for="compact">Compact catalogue cards<br><span class="small">Keep more references in view.</span></label></div><div class="check"><input type="checkbox" id="motion" data-setting="motion" ${state.motion?'checked':''}><label for="motion">Reduce interface motion<br><span class="small">Use simpler transitions throughout.</span></label></div></section><section class="panel"><h2>Yours, on this browser.</h2><p style="margin:16px 0">Your progress, notes and goals are stored locally. Files live in this browser's private file database. There is no cloud account or cross-device sync.</p><p class="small">${state.enrolled.length} enrolled courses · ${state.sessions.length} sessions · ${files.length} local files</p><button data-action="export" style="margin-top:20px">${icon('file')}Export learning backup</button></section><section class="panel"><div class="section-head"><h2>Your goals</h2><button data-action="goal" aria-label="Add goal">${icon('plus')}</button></div>${state.goals.slice(0,3).map(goalRow).join('')||'<p class="small">Set your first goal to give structure to your curiosity.</p>'}</section></div></div>`}
function vault(embedded=false){return (embedded?'':head('YOUR LOCAL VAULT','Keep your own thinking close.','Add notes, PDFs and images that support your learning. Files stay in this browser.',`<button data-action="upload">${icon('upload')}Upload a file</button>`)+`<nav class="tabs"><a href="#/knowledge">Explore references</a><a class="active" href="#/knowledge/vault">My vault</a></nav>`)+`<section class="panel"><div class="section-head"><h2>${files.length} personal files</h2><button data-action="upload">${icon('plus')}Add file</button></div><p class="small" style="margin-bottom:20px">PDF, TXT, MD, JSON, PNG and JPG · up to 20 MB each · stored on this device</p>${files.length?files.map(f=>`<div class="row"><span class="iconbox blue">${icon('file')}</span><div class="grow"><h3>${esc(f.name)}</h3><span class="small">${(f.size/1024).toFixed(0)} KB · ${esc(f.date)}${f.course?' · '+esc(C.find(c=>c.id===f.course)?.title||''):''}${f.domain!==''&&f.domain!=null?' · '+esc(D[+f.domain]?.name||''):''}</span></div><button data-action="download-file" data-id="${f.id}">Download</button><button data-action="delete-file" data-id="${f.id}" aria-label="Delete ${esc(f.name)}">${icon('close')}</button></div>`).join(''):empty('A home for your own notes.','Add a study guide or a reflection. Your uploaded files will be available after reload.')}</section><section class="panel"><h2>Your saved references</h2><div class="resources" style="margin-top:20px">${resources.filter(r=>state.saved.includes(r.url)).slice(0,24).map(resourceCard).join('')}</div>${!state.saved.length?'<p style="margin-top:15px">Bookmark a reference to collect it here.</p>':''}</section>`}
function missing(){return head('PAGE NOT FOUND','This path is still unwritten.','Choose a section from your workspace.',btn('Back to the dashboard','#/dashboard',true))}
function render(){shell();let html;if(view.page==='dashboard')html=dashboard();else if(view.page==='domains')html=view.id?domainDetail():domains();else if(view.page==='courses')html=view.id&&view.id!=='my-learning'?courseDetail():courses();else if(view.page==='knowledge')html=knowledge();else if(view.page==='jobs')html=jobs();else if(view.page==='profile')html=profile();else if(view.page==='analytics')html=analytics();else html=missing();if(view.page==='dashboard'&&state.saved.length)html+=`<section class="panel"><div class="section-head"><h2>Kept for another day</h2><a class="textlink" href="#/knowledge/vault">Your saved references ↗</a></div><div class="resources">${resources.filter(r=>state.saved.includes(r.url)).slice(0,4).map(resourceCard).join('')}</div></section>`;$('#main').innerHTML=html}
function parseRoute(){const parts=(location.hash||'#/dashboard').replace(/^#\/?/,'').split('/');view={page:parts[0]||'dashboard',id:parts[1],tab:parts[2]};filter={q:'',cat:'All',level:'All',type:'All',source:'All',domain:'All',saved:false,mode:'grid',city:filter.city||'Bengaluru',sort:'title'};limit=24;render();closeDrawer(false);window.scrollTo(0,0)}
function openModal(html){const modal=$('#modal');modal.innerHTML=`<button class="close" data-action="close" aria-label="Close dialog">${icon('close')}</button>${html}`;const heading=modal.querySelector('h2');if(heading){heading.id='dialog-title';modal.setAttribute('aria-labelledby','dialog-title')}modal.showModal()}
function sessionForm(course=''){openModal(`<h2>Make time count.</h2><p style="margin-bottom:20px">Record a study session you have completed.</p><form id="session-form"><div class="formfield"><label for="session-title">What did you study?</label><input id="session-title" name="title" maxlength="160" required placeholder="e.g. Python functions and a small practice lab"></div><div class="twocol"><div class="formfield"><label for="session-minutes">Minutes · 1–720 per day</label><input id="session-minutes" name="minutes" type="number" min="1" max="720" value="30" required></div><div class="formfield"><label for="session-date">Study date</label><input id="session-date" name="date" type="date" max="${localDate()}" value="${localDate()}" required></div></div><div class="formfield"><label for="session-course">Associate with a course</label><select id="session-course" name="course"><option value="">Independent learning</option>${C.filter(c=>state.enrolled.includes(c.id)).map(c=>`<option value="${c.id}" ${course===c.id?'selected':''}>${esc(c.title)}</option>`).join('')}</select></div><div class="form-actions"><button type="button" data-action="close">Cancel</button><button class="black" type="submit">Save session</button></div></form>`)}
function goalForm(course='',id=''){const g=state.goals.find(g=>g.id===id)||{};course=g.course||course;openModal(`<h2>${id?'Refine your intention.':'Give curiosity a direction.'}</h2><form id="goal-form" data-id="${id}"><div class="formfield"><label for="goal-title">Your goal</label><input id="goal-title" name="title" maxlength="160" value="${esc(g.title||'')}" required placeholder="e.g. Finish my first Python project"></div><div class="formfield"><label for="goal-date">Target date · optional</label><input id="goal-date" name="date" type="date" value="${esc(g.date||'')}"></div><div class="formfield"><label for="goal-course">Learning path · optional</label><select id="goal-course" name="course"><option value="">Independent goal</option>${C.map(c=>`<option value="${c.id}" ${course===c.id?'selected':''}>${esc(c.title)}</option>`).join('')}</select></div><div class="formfield"><label for="goal-checkpoint">Checkpoint · optional</label><select id="goal-checkpoint" name="checkpoint"><option value="">Whole course / personal goal</option>${(C.find(c=>c.id===course)?.modules||[]).map(m=>`<option value="${m.id}" ${g.checkpoint===m.id?'selected':''}>${esc(m.title)}</option>`).join('')}</select></div><div class="form-actions"><button type="button" data-action="close">Cancel</button><button class="black" type="submit">Save goal</button></div></form>`)}
function searchModal(){openModal(`<h2>Follow your curiosity.</h2><input type="search" id="global-search" placeholder="Search domains, courses and references…" aria-label="Global search" style="width:100%;margin-bottom:16px"><div class="search-results" id="search-results"><p class="small">Start typing a topic or skill.</p></div>`);$('#global-search').focus()}
function uploadForm(){openModal(`<h2>Add to your local vault.</h2><form id="upload-form"><p class="small" style="margin-bottom:20px">Files stay in this browser. PDF, TXT, MD, JSON, PNG and JPG. Maximum 20 MB.</p><div class="formfield"><label for="upload-file">Choose a file</label><input id="upload-file" name="file" type="file" accept=".pdf,.txt,.md,.json,.png,.jpg,.jpeg" required></div><div class="formfield"><label for="upload-course">Course association · optional</label><select id="upload-course" name="course"><option value="">None</option>${C.map(c=>`<option value="${c.id}">${esc(c.title)}</option>`).join('')}</select></div><div class="formfield"><label for="upload-domain">Domain association · optional</label><select id="upload-domain" name="domain"><option value="">None</option>${D.map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('')}</select></div><div class="form-actions"><button type="button" data-action="close">Cancel</button><button class="black" type="submit">Save file locally</button></div></form>`)}
function db(){return new Promise((resolve,reject)=>{const r=indexedDB.open('zeta-web-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('files',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function fileOperation(kind,value){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('files',kind==='getAll'||kind==='get'?'readonly':'readwrite'),store=tx.objectStore('files');const request=kind==='getAll'?store.getAll():store[kind](value);let result;request.onsuccess=()=>result=request.result;request.onerror=()=>reject(request.error);tx.oncomplete=()=>{database.close();resolve(result)};tx.onerror=()=>{database.close();reject(tx.error)}})}
async function refreshFiles(){try{files=(await fileOperation('getAll')).map(({blob,...metadata})=>metadata);render()}catch{toast('Local file storage is unavailable in this browser.')}}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',async e=>{const scroll=e.target.closest('[data-scroll]');if(scroll){e.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:state.motion?'instant':'smooth'});return}const lesson=e.target.closest('[data-lesson]');if(lesson){const n=lesson.dataset.lesson;setTimeout(()=>document.getElementById('module-'+n)?.scrollIntoView(),80)}const cat=e.target.closest('[data-cat]');if(cat){filter.cat=cat.dataset.cat;limit=24;render();return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(a==='close')$('#modal').close();else if(a==='menu'){openDrawer()}else if(a==='drawer-close'){closeDrawer()}else if(a==='search')searchModal();else if(a==='session')sessionForm(b.dataset.course);else if(a==='goal')goalForm(b.dataset.course);else if(a==='edit-goal')goalForm('',id);else if(a==='upload')uploadForm();else if(a==='enroll')mutate(()=>{if(!state.enrolled.includes(id))state.enrolled.push(id)},'Added to your learning paths');else if(a==='bookmark'){const kind=b.dataset.kind,key=kind==='domains'?+id:id;mutate(()=>state[kind]=state[kind].includes(key)?state[kind].filter(i=>i!==key):[...state[kind],key])}else if(a==='more'){limit+=24;render()}else if(a==='toggle-saved'){filter.saved=!filter.saved;limit=24;render()}else if(a==='view-mode'){filter.mode=filter.mode==='grid'?'table':'grid';render()}else if(a==='reset'){filter={...filter,q:'',cat:'All',type:'All',source:'All',level:'All',domain:'All',saved:false};render()}else if(a==='note'){const value=document.querySelector(`[data-note="${id}"]`).value;mutate(()=>state.notes[id]=value,'Reflection saved')}else if(a==='delete-goal')mutate(()=>state.goals=state.goals.filter(g=>g.id!==id),'Goal deleted');else if(a==='delete-session')mutate(()=>state.sessions=state.sessions.filter(s=>s.id!==id),'Session deleted');else if(a==='pdf')planner(+b.dataset.domain);else if(a==='export')download(new Blob([JSON.stringify({schema:'zeta-web-backup-v1',exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}),'zeta-learning-backup.json');else if(a==='download-file'){try{const f=await fileOperation('get',id);if(f)download(f.blob,f.name);else toast('This file is no longer available.')}catch{toast('The file could not be read.')}}else if(a==='delete-file'){try{await fileOperation('delete',id);await refreshFiles();toast('File deleted from this browser')}catch{toast('File deletion failed.')}}});
document.addEventListener('input',e=>{if(e.target.id==='global-search'){const q=e.target.value.trim().toLowerCase();let hits=[];if(q){D.filter(d=>`${d.name} ${d.skills.join(' ')}`.toLowerCase().includes(q)).slice(0,8).forEach(d=>hits.push({title:d.name,type:'Domain',url:route('domains',d.id)}));C.filter(c=>`${c.title} ${c.skills.join(' ')}`.toLowerCase().includes(q)).slice(0,8).forEach(c=>hits.push({title:c.title,type:'Course',url:route('courses',c.id)}));resources.filter(r=>r.title.toLowerCase().includes(q)).slice(0,8).forEach(r=>hits.push({title:r.title,type:'Online reference',url:r.url}))}$('#search-results').innerHTML=hits.map(h=>`<a href="${esc(h.url)}" ${h.url.startsWith('http')?'target="_blank" rel="noopener noreferrer"':''}><span class="small">${h.type}</span><h3>${esc(h.title)}</h3></a>`).join('')||`<p class="small">${q?'No results. Try another topic.':'Start typing a topic or skill.'}</p>`;return}if(e.target.dataset.filter==='q'){const pos=e.target.selectionStart;filter.q=e.target.value;limit=24;render();const input=$('[data-filter="q"]');input?.focus();input?.setSelectionRange(pos,pos)}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.filter){filter[t.dataset.filter]=t.value;limit=24;render()}else if(t.dataset.module){if(!state.enrolled.some(id=>C.find(c=>c.id===id)?.modules.some(m=>m.id===t.dataset.module)))return;mutate(()=>state.completed=t.checked?[...new Set([...state.completed,t.dataset.module])]:state.completed.filter(id=>id!==t.dataset.module))}else if(t.dataset.milestone)mutate(()=>state.milestones=t.checked?[...new Set([...state.milestones,t.dataset.milestone])]:state.milestones.filter(id=>id!==t.dataset.milestone));else if(t.dataset.goal)mutate(()=>state.goals.find(g=>g.id===t.dataset.goal).done=t.checked);else if(t.dataset.setting)mutate(()=>state[t.dataset.setting]=t.checked);else if(t.id==='goal-course'){const c=C.find(c=>c.id===t.value);$('#goal-checkpoint').innerHTML='<option value="">Whole course / personal goal</option>'+(c?.modules||[]).map(m=>`<option value="${m.id}">${esc(m.title)}</option>`).join('')}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,fd=new FormData(f);if(f.id==='profile-form'){const name=String(fd.get('name')).trim();if(!name){toast('Please add a preferred name.');return}mutate(()=>state.profile={name,intention:String(fd.get('intention')).trim(),skills:String(fd.get('skills')).slice(0,5000),interests:fd.getAll('interests').filter(i=>K.includes(i))},'Your profile is saved')}else if(f.id==='session-form'){const title=String(fd.get('title')).trim(),date=String(fd.get('date')),minutes=Number(fd.get('minutes')),course=String(fd.get('course'));if(!title||!Number.isInteger(minutes)||minutes<1||minutes>720||!/^\d{4}-\d{2}-\d{2}$/.test(date)||Number.isNaN(new Date(date).getTime())||new Date(date+'T12:00:00').getDate()!==Number(date.slice(-2))||date>localDate()||state.sessions.filter(s=>s.date===date).reduce((a,s)=>a+s.minutes,0)+minutes>720){toast('Use a valid past or current date and 1–720 total minutes per day.');return}const previous=structuredClone(state);state.sessions.push({id:crypto.randomUUID(),title,minutes,date,course});if(save()){$('#modal').close();toast('Study session recorded');render()}else {state=previous;render()}}else if(f.id==='goal-form'){const title=String(fd.get('title')).trim();if(!title)return;const id=f.dataset.id||crypto.randomUUID(),old=state.goals.find(g=>g.id===id),previous=structuredClone(state);state.goals=state.goals.filter(g=>g.id!==id);state.goals.push({id,title,date:String(fd.get('date')),course:String(fd.get('course')),checkpoint:String(fd.get('checkpoint')),done:old?.done||false});if(save()){$('#modal').close();toast('Learning goal saved');render()}else {state=previous;render()}}else if(f.id==='upload-form'){const file=fd.get('file');if(!file?.size||file.size>20*1024*1024||!/^.+\.(pdf|txt|md|json|png|jpe?g)$/i.test(file.name)){toast('Choose a supported file up to 20 MB.');return}const submit=f.querySelector('[type="submit"]');submit.disabled=true;submit.textContent='Saving…';try{await fileOperation('put',{id:crypto.randomUUID(),name:file.name,size:file.size,type:file.type,blob:file,date:localDate(),course:String(fd.get('course')),domain:String(fd.get('domain'))});$('#modal').close();await refreshFiles();toast('File saved to your local vault')}catch{toast('File storage failed. Check browser storage capacity.');submit.disabled=false;submit.textContent='Save file locally'}}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$('#modal').open)searchModal()}if(e.key==='Escape')closeDrawer()});$('#modal').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close()}if(e.target.closest('a'))e.currentTarget.close()});window.addEventListener('hashchange',parseRoute);parseRoute();refreshFiles();
/* Complete multi-page worksheet; all four roadmap stages remain in the download. */
function planner(domain){
 const d=D[domain],path=ZETA_LEARNING_PATHS[d.id],clean=s=>s.normalize('NFKD').replace(/[^\x20-\x7E]/g,'').replace(/[()\\]/g,'\\$&');
 const lines=['ZETA - PERSONAL STUDY PLANNER',d.name,'','Name: ____________________    Date: ____________________','Learning intention: _______________________________________',''];
 path.stages.forEach((s,i)=>lines.push(`STAGE ${i+1}: ${s.title}`,`Practice: ${s.exercise}`,`Checkpoint: ${s.checkpoint}`,'Notes: ____________________________________________________',''));
 lines.push('Session minutes: ______   Next step: ______________________','Source: ZETA authored roadmap. Self-assessment worksheet.');
 const wrapped=[];lines.forEach(line=>{while(line.length>90){let n=line.lastIndexOf(' ',90);if(n<1)n=90;wrapped.push(line.slice(0,n));line=line.slice(n).trim()}wrapped.push(line)});
 const pages=[];for(let i=0;i<wrapped.length;i+=52)pages.push(wrapped.slice(i,i+52));
 const kids=pages.map((_,i)=>`${4+i*2} 0 R`).join(' '),objects=['<< /Type /Catalog /Pages 2 0 R >>',`<< /Type /Pages /Kids [${kids}] /Count ${pages.length} >>`,'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>'];
 pages.forEach((lines,i)=>{const stream='BT /F1 10 Tf 45 790 Td 13 TL\n'+lines.map((line,n)=>(n?'T* ':'')+`(${clean(line)}) Tj`).join('\n')+'\nET';objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R >> >> /Contents ${5+i*2} 0 R >>`,`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`)});
 let pdf='%PDF-1.4\n',offsets=[0];objects.forEach((o,i)=>{offsets.push(pdf.length);pdf+=`${i+1} 0 obj\n${o}\nendobj\n`});const start=pdf.length;pdf+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n${offsets.slice(1).map(o=>String(o).padStart(10,'0')+' 00000 n ').join('\n')}\ntrailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${start}\n%%EOF`;download(new Blob([pdf],{type:'application/pdf'}),`zeta-${d.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')}-planner.pdf`)
}

function isMobile(){return typeof matchMedia==='function'&&matchMedia('(max-width:768px)').matches}
function syncDrawer(){const sidebar=$('#sidebar'),open=sidebar.classList.contains?sidebar.classList.contains('open'):false,mobile=isMobile();sidebar.inert=mobile&&!open;sidebar.setAttribute('aria-hidden',String(mobile&&!open));const backdrop=$('#drawer-backdrop');if(backdrop)backdrop.hidden=!mobile||!open;$('#workspace').inert=mobile&&open;document.body.style.overflow=mobile&&open?'hidden':'';const menu=$('[data-action="menu"]');menu?.setAttribute('aria-expanded',String(open));if(mobile&&open){sidebar.setAttribute('role','dialog');sidebar.setAttribute('aria-modal','true');sidebar.setAttribute('aria-label','Workspace navigation')}else{sidebar.removeAttribute?.('role');sidebar.removeAttribute?.('aria-modal')}}
function openDrawer(){if(!isMobile())return;$('#sidebar').classList.add('open');syncDrawer();$('#sidebar a')?.focus()}
function closeDrawer(restore=true){const sidebar=$('#sidebar'),wasOpen=sidebar.classList.contains?sidebar.classList.contains('open'):false;sidebar.classList.remove('open');syncDrawer();if(wasOpen&&restore)$('[data-action="menu"]')?.focus()}
document.addEventListener('keydown',e=>{if(e.key!=='Tab'||!isMobile()||!$('#sidebar').classList.contains('open'))return;const items=[...$('#sidebar').querySelectorAll('a,button')],first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}});window.addEventListener('resize',syncDrawer);
